87	  /// spec-7-2 — `export-download-get`'s own shape: the real payload is the
88	  /// `302` response's `Location` header (a signed Storage URL), never a
89	  /// JSON body. `followRedirects: false` stops dio from auto-following
90	  /// into that signed-storage host itself (Boundaries); the permissive
91	  /// `validateStatus` (anything below 400) keeps dio from throwing on the
92	  /// `302` the way its own default validator (`>= 200 && < 300`) would.
93	  /// `responseType` is deliberately left at its default — an *error*
94	  /// response (>= 400) still decodes as JSON, so `_mapDioException`/
95	  /// `dioErrorCodeOf` keep mapping it exactly as they do for every other
96	  /// call on this façade, unchanged.
97	  ///
98	  /// A `302` with no `Location` header (shouldn't happen — the contract's
99	  /// own response is declared as exactly this) maps to
100	  /// [Failure.malformedResponse] rather than returning an empty/null URL
101	  /// (RNF09, I/O matrix: "Missing Location").
102	  Future<Either<Failure, String>> getRedirectLocation(
103	    String function, {
104	    List<String> pathParams = const [],
105	    Map<String, dynamic>? queryParameters,
106	  }) async {
107	    try {
108	      final response = await _dio.get<dynamic>(
109	        _urlBuilder.build(function, pathParams),
110	        queryParameters: queryParameters,
111	        options: Options(
112	          followRedirects: false,
113	          validateStatus: (status) => status != null && status < 400,
114	        ),
115	      );
116	      final location = response.headers.value('location');
117	      if (location == null || location.isEmpty) {
118	        return left(
119	          const Failure.malformedResponse(message: 'Missing Location header'),
120	        );
121	      }
122	      return right(location);
123	    } on DioException catch (e) {
124	      return left(_mapDioException(e));
125	    } catch (e) {
126	      return left(Failure.malformedResponse(message: e.toString()));
127	    }
128	  }
129	
130	  /// spec-6-1 — streaming companion to [post]: sent with
131	  /// `ResponseType.stream` so the SSE response body never gets buffered
132	  /// into a single in-memory JSON blob the way [post]'s own
133	  /// `Dio.post<Map<String, dynamic>>` would. Each emitted `Right` is one
134	  /// raw, UTF-8-decoded chunk straight off the wire — SSE `event:`/`data:`
135	  /// line-splitting stays feature-local (`ChatRemoteDataSource`), this
136	  /// façade only owns the transport + error-mapping step (Boundaries:
137	  /// "ApiClient stays the one façade every datasource calls through").
138	  /// `allowMalformed: true` mirrors every other decode step in this app
139	  /// (RNF09: never throw on a malformed byte sequence) — a chunk that
140	  /// can't be exactly transcoded still degrades to the replacement
141	  /// character rather than crashing the stream.
142	  ///
143	  /// A connection that closes cleanly with no further error is simply a
144	  /// stream that ends with no further `Right`/`Left` emitted — detecting
145	  /// that as a "mid-stream drop" (no `done`/`error` SSE event ever seen)
146	  /// is the caller's job, not this method's; `ApiClient` has no notion of
147	  /// the SSE event grammar.
148	  Stream<Either<Failure, String>> postStream(
149	    String function, {
150	    List<String> pathParams = const [],
151	    Object? data,
152	  }) async* {
153	    try {
154	      final response = await _dio.post<ResponseBody>(
155	        _urlBuilder.build(function, pathParams),
156	        data: data,
157	        // `receiveTimeout: Duration.zero` overrides `BaseOptions`' own 30s
158	        // (set for every other, non-streaming call) for this one request —
159	        // dio restarts that timer on every received chunk (including the
160	        // gap before the very first one), so it fires mid-generation
161	        // whenever the RAG+LLM pipeline takes longer than 30s to flush the
162	        // next SSE event, aborting the connection client-side while the
163	        // backend keeps running and persists the full answer regardless
164	        // (bug: the aborted bubble then shows `failed` for an answer that
165	        // actually succeeded, and a later retry — finding no `serverId`,
166	        // since even `message_created` never arrived — resends as a brand
167	        // new message instead of regenerating in place). The backend's own
168	        // `AI_GENERATION_TIMEOUT` in-band `error` event (`error-taxonomy.md`,
169	        // already mapped by `_parseEvent`) is this call's real circuit
170	        // breaker for a generation that's actually stuck — no client-side
171	        // receive-gap timeout is needed on top of it here.
172	        // `persistentConnection: false` — every other call on this `Dio`
173	        // instance happily reuses a pooled keep-alive connection, but this
174	        // one follows `chat-sessions-list`/`chat-messages-list` (fired by
175	        // `ChatCubit.init()` on every Home/Chat mount) against the same
176	        // host, then sits idle while the user types. On a real network the
177	        // edge/CDN in front of the backend closes that idle pooled
178	        // connection well before the user hits send; `dart:io`'s
179	        // `HttpClient` doesn't notice until it tries to reuse it, surfacing
180	        // as a connection error with no response (`e.response == null`),
181	        // which `dioErrorCodeOf` maps to `NETWORK_OFFLINE` —
182	        // `RetryInterceptor` never retries this function (duplicate-send
183	        // guard), so it reaches here as an immediate, silent `Left` with
184	        // zero SSE bytes ever read: an empty bubble marked `failed` within
185	        // ~1-2s, indistinguishable on screen from a real network failure.
186	        // Forcing a brand-new connection for every send/retry (never
187	        // reusing the pool) removes the race entirely — reproduces
188	        // reliably on a physical device over Wi-Fi, never on
189	        // localhost/simulator (negligible latency, no real idle-close
190	        // policy) or a one-off external call (never reuses this app's own
191	        // pooled connection to begin with).
192	        options: Options(
193	          responseType: ResponseType.stream,
194	          receiveTimeout: Duration.zero,
195	          persistentConnection: false,
196	        ),
197	      );
198	      final body = response.data;
199	      if (body == null) {
200	        yield left(
201	          const Failure.malformedResponse(message: 'Empty stream body'),
202	        );
203	        return;
204	      }
205	      // `Utf8Decoder.bind` (not a per-chunk `utf8.decode`) carries any
206	      // incomplete trailing multi-byte sequence over to the next chunk —
207	      // required here since dio's own chunk boundaries split on byte
208	      // count, not on character boundaries, and this app's primary
209	      // language (pt-BR) uses multi-byte UTF-8 characters constantly.
210	      await for (final text in const Utf8Decoder(
211	        allowMalformed: true,
212	      ).bind(body.stream)) {
213	        yield right(text);
214	      }
215	    } on DioException catch (e) {
216	      // Diagnostic only (RNF09: the mapped `Failure` below is still what
217	      // actually reaches the UI) — every other failure path in this file
218	      // swallows the real exception silently, which is exactly what made
219	      // this stream's own dropped-connection failures invisible on-device
220	      // with nothing printed to the console. Kept past this specific
221	      // investigation: a silent transport failure here is always worth a
222	      // trace, the same rationale `HeaderInterceptor`'s own `debugPrint`
223	      // calls already follow.
224	      debugPrint(
225	        'ApiClient.postStream: DioException ${e.type} on '
226	        '${e.requestOptions.path} — ${e.message ?? e.error}',
227	      );
228	      yield left(await _mapStreamDioException(e));
229	    } catch (e) {
230	      debugPrint('ApiClient.postStream: unexpected error — $e');
231	      yield left(Failure.malformedResponse(message: e.toString()));
232	    }
233	  }
234	
235	  /// [postStream]'s own error-mapping step. A non-2xx response to a
236	  /// `ResponseType.stream` request is never auto-decoded into a `Map` by
237	  /// dio's default transformer (dio's own contract: "you must return the
238	  /// responseBody when Options.responseType is stream") — [e.response]'s
239	  /// `data` is still the raw, undrained [ResponseBody] at this point, so
240	  /// [_mapDioException]'s own `data is Map` check always misses it and
241	  /// would otherwise collapse every real backend error code on this one
242	  /// streaming endpoint into [Failure.malformedResponse]. Draining and
243	  /// decoding it here, once, keeps that same `{code, message}` mapping
244	  /// (`error-taxonomy.md`) correct for the stream path too, without
245	  /// changing [_mapDioException]/`dioErrorCodeOf` themselves — both are
246	  /// shared with `RetryInterceptor`, which never sees a stream response at
247	  /// all (it retries before dio's transformer runs), so widening their
248	  /// `Map`-only contract isn't needed here. Any failure to drain/decode
249	  /// (including a non-JSON body) falls back to [_mapDioException]'s own
250	  /// generic mapping unchanged.
251	  Future<Failure> _mapStreamDioException(DioException e) async {
252	    final data = e.response?.data;
253	    if (data is ResponseBody) {
254	      try {
255	        final bytes = await data.stream.expand((chunk) => chunk).toList();
256	        final decoded = jsonDecode(utf8.decode(bytes, allowMalformed: true));
257	        if (decoded is Map && decoded['code'] is String) {
258	          final message = decoded['message'];
259	          final failure = Failure.fromCode(
260	            decoded['code'] as String,
261	            (message is String ? message : null) ?? 'Unknown error',
262	          );
263	          if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
264	            _sessionExpiryNotifier.notifyExpired();
265	          }
266	          return failure;
267	        }
268	      } catch (_) {
269	        // Falls through to the generic mapping below — same "never throw"
270	        // rationale every other decode step in this file already follows.
271	      }
272	    }
273	    return _mapDioException(e);
274	  }
275	
276	  Future<Either<Failure, Map<String, dynamic>>> _send(
277	    Future<Response<Map<String, dynamic>>> Function() request,
278	  ) async {
279	    try {
280	      final response = await request();
281	      final data = response.data;
282	      if (data == null) {
283	        return left(
284	          const Failure.malformedResponse(message: 'Empty response body'),
285	        );
286	      }
287	      return right(data);
288	    } on DioException catch (e) {
289	      return left(_mapDioException(e));
290	    } catch (e) {
291	      return left(Failure.malformedResponse(message: e.toString()));
292	    }
293	  }
294	
295	  Failure _mapDioException(DioException e) {
296	    final code = dioErrorCodeOf(e);
297	    if (code == null) {
298	      // Covers a cancelled request and an HTTP response that doesn't carry
299	      // the expected `{code, message, retryable}` body — neither is one of
300	      // the 13 backend codes, so neither is retryable (dioErrorCodeOf).
301	      return Failure.malformedResponse(
302	        message: e.message ?? 'Malformed response',
303	      );
304	    }
305	    final data = e.response?.data;
306	    final message = data is Map ? data['message'] : null;
307	    final failure = Failure.fromCode(
308	      code,
309	      (message is String ? message : null) ?? e.message ?? 'Unknown error',
310	    );
311	    if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
312	      _sessionExpiryNotifier.notifyExpired();
313	    }
314	    return failure;
315	  }
316	
317	  /// Whether [e]'s request targeted one of the three `security: []`
318	  /// operations (signup, login, refresh) — the only calls `AUTH_EXPIRED`
319	  /// must never be treated as a mid-session expiry for, since those are the
320	  /// anon-keyed calls Story 1.4's `restoreSession()` itself makes.
321	  ///
322	  /// Mirrors `HeaderInterceptor.onRequest`'s own fail-open behavior: a
323	  /// malformed `requestOptions.path` (shouldn't happen — `UrlBuilder`
324	  /// always produces a valid URL) is treated as "not anon-key-only" rather
325	  /// than letting a `FormatException` escape this mapping step unmapped
326	  /// (RNF09).
327	  bool _isAnonKeyOnlyCall(DioException e) {
328	    String function;
329	    try {
330	      function = HeaderInterceptor.functionNameOf(e.requestOptions.path);
331	    } catch (_) {
332	      function = '';
333	    }
334	    return HeaderInterceptor.anonKeyOnlyFunctions.contains(function);
335	  }
