9	/// Drives `EntriesSearchBar`/`MeusRegistrosScreen`'s docked search surface
10	/// (spec-5-1) — the first real `Resource<T>` consumer (AD-12: "single data
11	/// source, single fetch" is exactly this screen's search slice, unlike
12	/// `MeusRegistrosState`'s own paginated shape). A DI `lazySingleton`
13	/// (Code Map), mirroring `MeusRegistrosCubit`: long-lived, so a query
14	/// already typed survives leaving and re-entering `/meus-registros` within
15	/// the same app session — though [onQueryChanged] is never called except
16	/// by the live `EntriesSearchBar`'s own `onChanged`, there is no
17	/// "re-run the last query on return" behavior to preserve here beyond the
18	/// cubit simply outliving the screen like `MeusRegistrosCubit` already
19	/// does.
20	class EntriesSearchCubit extends Cubit<Resource<List<Entry>>> {
21	  EntriesSearchCubit(this._repository) : super(const ResourceIdle());
22	
23	  final EntriesRepository _repository;
24	
25	  /// `EntriesSearchBar`'s own debounce window (I/O matrix: "5 keystrokes
26	  /// within 300ms -> exactly one `entries-search` call fires, for the
27	  /// final value").
28	  static const _debounceDuration = Duration(milliseconds: 300);
29	
30	  Timer? _debounceTimer;
31	
32	  /// A monotonic counter guarding against a stale in-flight [search] call's
33	  /// result landing after a newer one has already changed the state —
34	  /// mirrors `MeusRegistrosCubit._generation` exactly. Bumped both when a
35	  /// new debounced search actually starts *and* when the query is cleared
36	  /// back to idle (Boundaries' "Stale response" row: an in-flight query A
37	  /// must never land once query B — even an empty one — has already
38	  /// superseded it).
39	  int _generation = 0;
40	
41	  /// spec-5-3 — this cubit's own copy of the active filter selection
42	  /// (Design Notes: filter state is duplicated, never shared —
43	  /// `MeusRegistrosCubit` importing/being imported by this cubit would
44	  /// violate RNF06; `MeusRegistrosScreen` is the only legitimate bridge,
45	  /// via [updateFilters]). `null` for each field means "no filter of that
46	  /// kind", same convention `MeusRegistrosCubit`'s own
47	  /// `_activeSource`/`_activeDateFrom`/`_activeDateTo` already use.
48	  EntrySource? _activeSource;
49	  DateTime? _activeDateFrom;
50	  DateTime? _activeDateTo;
51	
52	  /// The current (trimmed) query text, kept in lockstep with every
53	  /// [onQueryChanged] call — empty exactly when idle (Boundaries:
54	  /// "While idle: silent storage, no call"), non-empty for as long as the
55	  /// search box holds a non-empty term, regardless of whether the
56	  /// debounced [_search] for it has actually fired yet. [updateFilters]
57	  /// reads this to decide whether a filter change needs to re-run a
58	  /// search at all.
59	  String _lastQuery = '';
60	
61	  /// `EntriesSearchBar.onChanged`'s one call site — [raw] is the text
62	  /// field's current (untrimmed) value on every keystroke. Cancels any
63	  /// pending debounce `Timer` first, regardless of outcome below (Code
64	  /// Map/Boundaries): a keystroke always supersedes whatever this cubit
65	  /// was about to do next.
66	  void onQueryChanged(String raw) {
67	    _debounceTimer?.cancel();
68	    final query = raw.trim();
69	    _lastQuery = query;
70	    if (query.isEmpty) {
71	      // I/O matrix: "Query cleared" — no request, pending work discarded,
72	      // timeline shown. Bumping the generation here (not only inside
73	      // [_search]) is what actually discards an already-in-flight
74	      // previous query's result once it resolves.
75	      _generation++;
76	      // Review finding: `close()` can race this synchronous call too (a
77	      // fast app teardown landing between a keystroke and this handler) —
78	      // same `isClosed` rationale `_search`'s own guard below already
79	      // documents; `emit()` after `close()` would otherwise throw.
80	      if (isClosed) {
81	        return;
82	      }
83	      emit(const ResourceIdle());
84	      return;
85	    }
86	    _debounceTimer = Timer(_debounceDuration, () => _search(query));
87	  }
88	
89	  /// spec-5-3 — `EntriesFilterSheet`'s "Aplicar", `_ActiveFiltersRow`'s
90	  /// chip-remove ×2, and "Limpar filtros", all via `MeusRegistrosScreen`'s
91	  /// own bridge (Design Notes) — called right alongside the existing
92	  /// `MeusRegistrosCubit.applyFilters()`/`clearFilters()` call, never in
93	  /// place of it. Also called unconditionally from `MeusRegistrosScreen.
94	  /// initState()` on every mount (Boundaries: "no stale filter carried
95	  /// forward"). Always stores [source]/[dateFrom]/[dateTo] regardless of
96	  /// whether a search is active (Boundaries: "always stores the fields").
97	  ///
98	  /// Only when [_lastQuery] is non-empty — a search is actually active —
99	  /// *and* at least one of [source]/[dateFrom]/[dateTo] actually differs
100	  /// from what was already stored, *or* the last search attempt failed
101	  /// (review finding: a filter-triggered re-search landing in
102	  /// `ResourceError` must stay retriable even when the user reapplies the
103	  /// exact same selection — `_SearchErrorState` has no retry button of its
104	  /// own, so silently no-op'ing here would strand the user with no visible
105	  /// recovery short of editing the search text) — the unchanged-and-ok case
106	  /// still short-circuits (review finding: skips a wasted `entries-search`
107	  /// network call when `initState()`'s own unconditional reset finds
108	  /// nothing to actually reset) — does this cancel any pending debounce and
109	  /// immediately re-run [_search] with that same term and the just-stored
110	  /// filters (Boundaries: "no debounce on the filter-triggered re-search");
111	  /// while idle, the new selection is simply kept for whenever the next
112	  /// query starts.
113	  void updateFilters({
114	    EntrySource? source,
115	    DateTime? dateFrom,
116	    DateTime? dateTo,
117	  }) {
118	    final filtersChanged =
119	        source != _activeSource ||
120	        dateFrom != _activeDateFrom ||
121	        dateTo != _activeDateTo;
122	    _activeSource = source;
123	    _activeDateFrom = dateFrom;
124	    _activeDateTo = dateTo;
125	    if (_lastQuery.isEmpty || (!filtersChanged && state is! ResourceError)) {
126	      return;
127	    }
128	    // Review finding: `close()` can race this call too (e.g. `initState()`
129	    // now calls this unconditionally on every mount) — same `isClosed`
130	    // rationale `onQueryChanged`'s own guard above documents; `_search()`'s
131	    // first line is `emit(ResourceLoading())`, which would otherwise throw
132	    // after `close()`.
133	    if (isClosed) {
134	      return;
135	    }
136	    _debounceTimer?.cancel();
137	    _search(_lastQuery);
138	  }
139	
140	  Future<void> _search(String query) async {
141	    final generation = ++_generation;
142	    // Review finding: deliberately *not* `const` — `ResourceLoading<T>`
143	    // has no custom `==`, so `const ResourceLoading()` is a canonicalized
144	    // singleton instance. Two searches in a row (e.g. "an" still in
145	    // flight when "ans" debounces) would otherwise both emit that exact
146	    // same instance; `Cubit.emit` (package:bloc) skips re-emitting a state
147	    // `==` to the current one, so the second transition into loading
148	    // would silently no-op — `MeusRegistrosScreen._onSearchStateChanged`'s
149	    // listener never re-fires, and its 300ms skeleton timer never resets
150	    // for "ans", measuring RNF01's threshold from the wrong start time. A
151	    // fresh (non-const) instance is identity-distinct from the prior one
152	    // even though both are `ResourceLoading`, so `emit` always proceeds.
153	    emit(ResourceLoading());
154	    final result = await _repository.search(
155	      query,
156	      source: _activeSource,
157	      dateFrom: _activeDateFrom,
158	      dateTo: _activeDateTo,
159	    );
160	    // Mirrors `MeusRegistrosCubit.loadFirstPage`'s own guard: `close()` can
161	    // race this awaited call, and a newer query (or a clear back to idle)
162	    // can have superseded this one while it was in flight.
163	    if (isClosed || generation != _generation) {
164	      return;
165	    }
166	    result.match(
167	      (failure) => emit(ResourceError(failure)),
168	      (entries) => emit(ResourceData(entries)),
169	    );
170	  }
171	
172	  @override
173	  Future<void> close() {
174	    _debounceTimer?.cancel();
175	    return super.close();
176	  }
177	}
